# owner: platform
import unittest
from datetime import date

from rosterkit.models import Mark, Student
from rosterkit.notices import build_notice

PUPIL = Student("1001", "Thistle", "Bram", "A")


def _mark(day, status="absent", ident="1001"):
    return Mark(ident, date(2026, 10, day), status)


class NoticeTests(unittest.TestCase):
    def test_names_count_and_sorted_dates(self):
        marks = [_mark(9), _mark(5), _mark(7, "present")]
        self.assertEqual(
            build_notice(PUPIL, marks),
            "Bram Thistle missed 2 day(s): "
            "2026-10-05, 2026-10-09"
        )

    def test_other_student_is_rejected(self):
        marks = [_mark(5), _mark(6, ident="2002")]
        with self.assertRaises(ValueError):
            build_notice(PUPIL, marks)

    def test_no_absences_is_rejected(self):
        with self.assertRaises(ValueError):
            build_notice(PUPIL, [_mark(5, "late")])
